describe("하루 한도와 순서", () => {
	test("끌어올리기 대상 8개 중 6개만, 나머지는 daily-limit", () => {
		const eight = Array.from({ length: 8 }, (_, index) =>
			listing({ id: `p${index}`, title: String.fromCharCode(65 + index), price: 10_000, hearts: 0 }),
		);
		const summary = summarize(planOf(eight));
		expect(summary.bump).toBe(6);
		expect(summary.held).toBe(2);
		expect(
			planOf(eight)
				.filter((proposal) => proposal.action === "skip")
				.map((proposal) => proposal.id),
		).toEqual(["p6", "p7"]);
	});

	test("가격만 대상은 하루 한도를 쓰지 않는다", () => {
		const open = Array.from({ length: 7 }, (_, index) =>
			listing({ id: `p${index}`, title: `bump ${index}`, price: 10_000, hearts: 0, until: TODAY }),
		);
		const onlyPrice = aimed({ id: "x", title: "가격만", price: 300_000, hearts: 4, target: 295_000 });
		const proposals = planOf([...open, onlyPrice]);
		const summary = summarize(proposals);
		expect(summary.bump).toBe(6);
		expect(summary.priceOnly).toBe(1);
		// 한 칸을 못 받은 끌올 대상과 가격만 내리는 글이 같은 까닭을 달고, 가격은 따로 내린다.
		expect(summary.held).toBe(2);
		expect(proposals.find((proposal) => proposal.id === "p6")).toMatchObject({
			action: "skip",
			skipReason: "daily-limit",
		});
		expect(proposals.find((proposal) => proposal.id === "x")).toMatchObject({
			action: "price-only",
			blocked: "daily-limit",
		});
	});

	test("끌올 문구가 없는 글 → 오래된 끌올 → 제목", () => {
		const older = listing({ id: "old", title: "나", price: 10_000, hearts: 0, bumpAgoDays: 7 });
		const newest = listing({ id: "new", title: "가", price: 10_000, hearts: 0, bumpAgoDays: 2 });
		const never = listing({ id: "never", title: "다", price: 10_000, hearts: 0, bumpAgoDays: null });
		const otherNever = listing({ id: "other", title: "라", price: 10_000, hearts: 0, bumpAgoDays: null });
		const sorted = [newest, older, otherNever, never]
			.sort((left, right) => compareBumpOrder(left, right, TODAY))
			.map((item) => item.id);
		expect(sorted).toEqual(["never", "other", "old", "new"]);
	});

	test("노출 나이·마감이 같으면 제목보다 하트가 먼저다", () => {
		const quiet = listing({ id: "quiet", title: "하", price: 10_000, hearts: 0, bumpAgoDays: 9 });
		const looked = listing({ id: "looked", title: "가", price: 10_000, hearts: 1, bumpAgoDays: 9 });
		const sorted = [looked, quiet].sort((left, right) => compareBumpOrder(left, right, TODAY));
		expect(sorted.map((item) => item.id)).toEqual(["quiet", "looked"]);
	});

	test("하루 6칸은 노출이 오래된 글부터 채운다", () => {
		const fillers = Array.from({ length: 6 }, (_, index) =>
			listing({ id: `f${index}`, title: `f${index}`, price: 10_000, hearts: 0, bumpAgoDays: 3 }),
		);
		const stale = listing({ id: "stale", title: "가", price: 10_000, hearts: 9, bumpAgoDays: null, postedAgoDays: 21 });
		const bumped = planOf([...fillers, stale])
			.filter((proposal) => proposal.action === "bump")
			.map((proposal) => proposal.id);
		expect(bumped).toHaveLength(6);
		expect(bumped).toContain("stale");
		expect(bumped).not.toContain("f5");
	});
});

describe("한도 채움", () => {
	test("기본 하루 한도는 6개다", () => {
		expect(DEFAULT_RULES.dailyLimit).toBe(DAILY_BUMP_LIMIT);
		expect(DAILY_BUMP_LIMIT).toBe(6);
	});
	test("노출 나이가 같으면 마감 빠른 순, 같은 날이면 가격 높은 순, 날짜 없음은 맨 뒤", () => {
		const earlyHigh = listing({
			id: "eh",
			title: "가",
			price: 200_000,
			hearts: 5,
			bumpAgoDays: 3,
			until: "2026-10-27",
		});
		const earlyLow = listing({ id: "el", title: "나", price: 100_000, hearts: 5, bumpAgoDays: 3, until: "2026-10-27" });
		const late = listing({ id: "late", title: "다", price: 500_000, hearts: 5, bumpAgoDays: 3, until: "2026-10-29" });
		const none = listing({ id: "none", title: "라", price: 900_000, hearts: 5, bumpAgoDays: 3, until: null });
		const sorted = [none, late, earlyLow, earlyHigh]
			.sort((left, right) => compareBumpOrder(left, right, TODAY))
			.map((item) => item.id);
		expect(sorted).toEqual(["eh", "el", "late", "none"]);
	});

	test("노출 나이를 모르는 글이 많으면 마감·하트·가격 순으로 6칸을 채운다", () => {
		const preferred = Array.from({ length: 4 }, (_, index) =>
			listing({ id: `p${index}`, title: `p${index}`, price: 10_000, hearts: 0 }),
		);
		const rest = [
			listing({ id: "eh", title: "가", price: 200_000, hearts: 5, until: "2026-10-27" }),
			listing({ id: "el", title: "나", price: 100_000, hearts: 5, until: "2026-10-27" }),
			listing({ id: "late", title: "다", price: 500_000, hearts: 5, until: "2026-10-29" }),
			listing({ id: "none", title: "라", price: 900_000, hearts: 5 }),
		];
		const proposals = planOf([...preferred, ...rest]);
		const bumped = proposals.filter((proposal) => proposal.action === "bump").map((proposal) => proposal.id);
		expect(bumped).toEqual(["p0", "p1", "p2", "eh", "el", "late"]);
		expect(proposals.find((proposal) => proposal.id === "p3")?.action).toBe("skip");
		expect(proposals.find((proposal) => proposal.id === "none")?.action).toBe("skip");
	});

	test("제외한 글은 한도 채움에 넣지 않는다", () => {
		const preferred = listing({ id: "p", title: "p", price: 10_000, hearts: 0 });
		const excluded = listing({
			id: "off",
			title: "제외",
			price: 900_000,
			hearts: 8,
			until: "2026-10-26",
			included: false,
		});
		const fill = listing({ id: "on", title: "채움", price: 50_000, hearts: 8, until: "2026-10-28" });
		const proposals = planOf([preferred, excluded, fill]);
		expect(proposals.find((proposal) => proposal.id === "on")?.action).toBe("bump");
		expect(proposals.find((proposal) => proposal.id === "off")?.skipReason).toBe("excluded");
	});
});

describe("포함/제외", () => {
	test("제외한 글은 skipReason excluded 이고 스케줄이 있으면 제안 가격만 계산된다", () => {
		const [proposal] = planOf([
			aimed({ id: "off", title: "제외", price: 50_000, hearts: 0, target: 45_000, included: false }),
		]);
		expect(proposal.action).toBe("skip");
		expect(proposal.skipReason).toBe("excluded");
		expect(proposal.price).toBe(45_000);
	});

	test("제외한 글은 끌어올리기 한도를 차지하지 않는다", () => {
		const listings = [
			listing({ id: "a", title: "a", price: 10_000, hearts: 0 }),
			...Array.from({ length: 6 }, (_, index) =>
				listing({ id: `b${index}`, title: `b${index}`, price: 10_000, hearts: 0, included: false }),
			),
		];
		expect(summarize(planOf(listings)).bump).toBe(1);
	});
});

