import { describe, expect, test } from "bun:test";
import { DAILY_BUMP_LIMIT, MAX_BUMPS } from "./cooldown";
import {
	DEFAULT_RULES,
	MIN_BUMP_AGE_DAYS,
	STALE_EXPOSURE_DAYS,
	atMaxBumps,
	bumpEligible,
	compareBumpOrder,
	exposureAgeDays,
	flowFromNow,
	alreadyAppliedToday,
	guardSnapshot,
	inCooldown,
	linePrice,
	pricePath,
	priceUnit,
	proposeBatch,
	recentlyExposed,
	remainingDays,
	bumpedToday,
	scheduleFor,
	summarize,
	type Listing,
} from "./rules";

const TODAY = "2026-10-26";
const NOW = Date.parse("2026-10-26T10:00:00+09:00");

function listing(overrides: Partial<Listing> & Pick<Listing, "id" | "title" | "price" | "hearts">): Listing {
	return {
		views: 0,
		chats: 0,
		bumpAgoDays: null,
		postedAgoDays: null,
		bumpCount: null,
		bumpedAt: null,
		nextBumpAt: null,
		target: null,
		until: null,
		included: true,
		...overrides,
	};
}

/** 마감이 오늘이면 한 번에 타겟으로 맞춘다. */
function aimed(overrides: Partial<Listing> & Pick<Listing, "id" | "title" | "price" | "hearts" | "target">): Listing {
	return listing({ until: TODAY, ...overrides });
}

function planOf(listings: Listing[], today = TODAY, now = NOW) {
	return proposeBatch(listings, { ...DEFAULT_RULES }, today, now);
}

describe("구간 내림", () => {
	test("단위는 인하 계산값 기준 500 / 1,000 / 5,000", () => {
		expect(priceUnit(9_999.9)).toBe(500);
		expect(priceUnit(10_000)).toBe(1_000);
		expect(priceUnit(99_999)).toBe(1_000);
		expect(priceUnit(100_000)).toBe(5_000);
	});

	test("마지막 날은 타겟을 다시 내림하지 않는다", () => {
		expect(linePrice(300_000, 280_000, 0, 1)).toBe(280_000);
		expect(linePrice(20_000, 17_555, 0, 1)).toBe(17_555);
		expect(linePrice(300_000, 240_000, 3, 4)).toBe(240_000);
		expect(linePrice(10_000, 10_000, 0, 1)).toBe(10_000);
	});

	test("시작가에서 타겟까지 균등하게 나누고 구간으로 내린다", () => {
		expect(linePrice(300_000, 240_000, 0, 4)).toBe(285_000);
		expect(linePrice(50_000, 40_000, 0, 4)).toBe(47_000);
		expect(linePrice(17_550, 15_000, 0, 2)).toBe(16_000);
	});

	test("타겟이 시작가 이상이거나 0 이하면 바꾸지 않는다", () => {
		expect(linePrice(10_000, 12_000, 0, 3)).toBe(10_000);
		expect(linePrice(10_000, 0, 0, 3)).toBe(10_000);
	});

	test("타겟에는 마지막 날에만 닿는다", () => {
		const days = 20;
		const prices = Array.from({ length: days }, (_, index) => linePrice(130_000, 100_000, index, days));
		expect(prices.at(-1)).toBe(100_000);
		expect(prices.slice(0, -1).every((price) => price > 100_000)).toBe(true);
		for (let index = 1; index < days; index += 1) expect(prices[index]).toBeLessThanOrEqual(prices[index - 1]);
	});
});

describe("쭉 내려가는 흐름", () => {
	test("하루 인하폭이 내림 단위보다 작아도 날마다 내려간다", () => {
		const days = 14;
		const prices = Array.from({ length: days }, (_, index) => linePrice(11_000, 8_000, index, days));
		expect(prices.at(-1)).toBe(8_000);
		for (let index = 1; index < days; index += 1) expect(prices[index]).toBeLessThan(prices[index - 1]);
		expect(prices[0]).toBeLessThan(11_000);
	});

	test("인하폭이 100원보다 작으면 100원 단위로 내린다", () => {
		expect(linePrice(20_000, 19_000, 0, 20) % 100).toBe(0);
	});
});

describe("기간", () => {
	test("오늘을 포함한 날 수", () => {
		expect(remainingDays("2026-10-26", "2026-10-26")).toBe(1);
		expect(remainingDays("2026-10-26", "2026-10-29")).toBe(4);
		expect(remainingDays("2026-10-26", "2026-10-25")).toBe(0);
		expect(remainingDays("2026-10-26", "nope")).toBeNull();
	});

	test("마감이 지났으면 오늘 타겟으로 맞춘다", () => {
		const row = listing({
			id: "a",
			title: "가",
			price: 50_000,
			hearts: 0,
			target: 40_000,
			until: "2026-10-20",
		});

