import { describe, expect, test } from "bun:test";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { resolve } from "node:path";
import type { ActionLog } from "./action-log";
import { cooldownText, resetStop, runApprovedOnPhone, stopRequested, watchStopFile } from "./bump-phone";
import { parseCooldownText } from "./cooldown";
import type { AdbExec } from "./phone";

// 폰 정보는 .env 에만 둔다. 테스트는 가짜 모델을 쓴다.
process.env.PHONE_MODEL = "SM-X000";

const TIP = `<hierarchy>
	<node text="건조기" content-desc="" bounds="[40,300][900,360]" />
	<node text="판매팁: 2일 12시간 후에 끌어올릴 수 있어요" content-desc="" bounds="[40,700][1040,760]" />
	<node text="끌어올리기" content-desc="" bounds="[40,2000][1040,2100]" />
</hierarchy>`;

describe("쿨타임 문구", () => {
	test("덤프에서 판매팁 문구를 꺼내 다음 시각으로 옮긴다", () => {
		const text = cooldownText(TIP);
		expect(text).toBe("판매팁: 2일 12시간 후에 끌어올릴 수 있어요");
		expect(parseCooldownText(text as string, new Date("2026-10-28T10:00:00.000Z"))).toBe("2026-10-30T22:00:00.000Z");
	});

	test("content-desc 에만 있어도 꺼낸다", () => {
		const xml = `<node text="" content-desc="30분 후에 끌어올릴 수 있어요" bounds="[0,0][10,10]" />`;
		expect(cooldownText(xml)).toBe("30분 후에 끌어올릴 수 있어요");
	});

	test("문구가 없으면 null 이라 저장소를 건드리지 않는다", () => {
		expect(cooldownText(`<node text="건조기" content-desc="" bounds="[0,0][10,10]" />`)).toBeNull();
		expect(parseCooldownText("건조기", new Date("2026-10-28T10:00:00.000Z"))).toBeNull();
	});
});

describe("예약중 글", () => {
	const SERIAL = "192.0.2.9:5555";
	const xml = readFileSync(resolve(import.meta.dir, "fixtures/sales-reserved.xml"), "utf8");
	const title = "쿠자 316 통 5중 스텐 프라이팬 2개";

	function phone(taps: string[][]) {
		return (args: string[]) => {
			const joined = args.join(" ");
			if (args[0] === "mdns") return { status: 0, stdout: "x _adb-tls-connect._tcp 192.0.2.9:5555\n", stderr: "" };
			if (args[0] === "devices") return { status: 0, stdout: "192.0.2.9:5555\tdevice\n", stderr: "" };
			if (joined.includes("getprop")) return { status: 0, stdout: "SM-X000\n", stderr: "" };
			if (joined.includes("dumpsys window")) return { status: 0, stdout: "isKeyguardShowing=false", stderr: "" };
			if (joined.includes("cat /sdcard/window_dump.xml")) return { status: 0, stdout: xml, stderr: "" };
			if (joined.includes("input tap")) taps.push(args);
			return { status: 0, stdout: "", stderr: "" };
		};
	}

	const batch = {
		id: "b",
		status: "approved" as const,
		signature: "",
		runHour: 19,
		runMinute: 0,
		approvedAt: "2026-10-30T10:00:00.000Z",
		items: [
			{
				id: "kuja",
				title,
				action: "price-only" as const,
				proposedPrice: 120000,
				snapshot: { price: 130000, hearts: 28, views: 0, chats: 0 },
			},
		],
	};

	function book(reserved: string[]) {
		return {
			previousBumpCount: () => 0,
			recordBump: () => {},
			recordCooldown: () => {},
			recordReserved: (id: string) => reserved.push(id),
		};
	}

	/** `.droid` 가 붙은 AdbExec. 화면 XML 은 droid dump 가 주고, adb 로는 덤프를 읽지 않는다. */
	function droidPhone(adbCalls: string[][], droidCalls: string[][]) {
		const adb: AdbExec = (args) => {
			adbCalls.push(args);
			if (args.join(" ").includes("dumpsys window"))
				return { status: 0, stdout: "isKeyguardShowing=false", stderr: "" };
			return { status: 0, stdout: "", stderr: "" };
		};
		return Object.assign(adb, {
			droid: (args: string[]) => {
				droidCalls.push(args);
				return { status: 0, stdout: args[0] === "dump" ? xml : "", stderr: "" };
			},
		});
	}

	test("폰 화면이 예약중이면 저장소가 몰라도 누르지 않고 예약중으로 기록한다", () => {
		const taps: string[][] = [];
		const reserved: string[] = [];
		const run = runApprovedOnPhone(batch, phone(taps), undefined, {
			log: quietLog(),
			// 폰 찾기는 droid 가 한다. 여기서는 이미 찾은 시리얼을 넣는다.
			findSerial: () => SERIAL,
			book: book(reserved),
		});
		expect(run).toMatchObject({ pricedOnly: 0, bumped: 0, skipped: 1, stopped: false });
		expect(taps).toEqual([]);
		expect(reserved).toEqual(["kuja"]);
	});

	test("droid 가 있으면 화면은 droid dump 로 읽고 uiautomator 는 부르지 않는다", () => {
		const adbCalls: string[][] = [];
		const droidCalls: string[][] = [];
		const reserved: string[] = [];
		const run = runApprovedOnPhone(batch, droidPhone(adbCalls, droidCalls), undefined, {
			log: quietLog(),
			findSerial: () => SERIAL,
			book: book(reserved),
		});

		expect(run).toMatchObject({ pricedOnly: 0, bumped: 0, skipped: 1, stopped: false });
		expect(reserved).toEqual(["kuja"]);
		expect(droidCalls).toContainEqual(["dump", "--serial", SERIAL]);
		expect(adbCalls.some((args) => args.includes("uiautomator") || args.includes("cat"))).toBe(false);
	});
});

describe("더보기 탭이 먹히지 않을 때", () => {
	const SERIAL = "192.0.2.9:5555";
	const xml = readFileSync(resolve(import.meta.dir, "fixtures/sales-dump.xml"), "utf8");
	const batch = {
		id: "b",
		status: "approved" as const,
		signature: "",
		runHour: 19,
		runMinute: 0,
		approvedAt: "2026-11-06T10:00:00.000Z",
		items: [
			{
				id: "kimchi",
				title: "LG 김치냉장고 K419TS15E",
				action: "price-only" as const,
				proposedPrice: 290000,
				snapshot: { price: 300000, hearts: 0, views: 0, chats: 0 },
			},
		],
	};

	// 메뉴가 안 열리는 폰: 화면은 늘 목록이다. 목록이 미끄러지는 중에 누른 탭을 흉내 낸다.
	function deadTapPhone(taps: string[][]) {
		const adb: AdbExec = (args) => {
			if (args.join(" ").includes("dumpsys window")) return { status: 0, stdout: "isKeyguardShowing=false", stderr: "" };
			if (args.join(" ").includes("input tap")) taps.push(args);
			return { status: 0, stdout: "", stderr: "" };
		};
		return Object.assign(adb, {
			droid: (args: string[]) => ({ status: 0, stdout: args[0] === "dump" ? xml : "", stderr: "" }),
		});
	}

	test("메뉴가 안 열리면 멈춘 화면을 다시 읽어 한 번 더 누른 뒤 건너뛴다", () => {
		const taps: string[][] = [];
		const run = runApprovedOnPhone(batch, deadTapPhone(taps), undefined, {
			log: quietLog(),
			findSerial: () => SERIAL,
			book: { previousBumpCount: () => 0, recordBump: () => {}, recordCooldown: () => {} },
		});
		const more = taps.filter((args) => args.join(" ").includes("input tap 9"));
		expect(more).toHaveLength(2);
		expect(run).toMatchObject({ pricedOnly: 0, bumped: 0, stopped: false });
	}, 30000);
});

describe("처리 순서", () => {
	const SERIAL = "192.0.2.9:5555";
	const list = readFileSync(resolve(import.meta.dir, "fixtures/sales-dump.xml"), "utf8");
	// 창이 안 열리고 쿨타임 안내만 뜨는 폰. 탭 뒤에는 안내가, 뒤로 가기 뒤에는 목록이 보인다.
	const tip = `<hierarchy><node text="판매팁: 2일 후에 끌어올릴 수 있어요" content-desc="" bounds="[40,700][1040,760]" /></hierarchy>`;
	const item = (title: string, action: "bump" | "price-only", proposedPrice: number) => ({
		id: title,
		title,
		action,
		proposedPrice,
		snapshot: { price: 300000, hearts: 0, views: 0, chats: 0 },
	});

	test("화면 맨 아래(노출이 가장 오래된) 글부터 한 번에 위로 걸으며 누른다", () => {
		let screen = list;
		const taps: number[][] = [];
		const adb: AdbExec = (args) => {
			const joined = args.join(" ");
			if (joined.includes("dumpsys window")) return { status: 0, stdout: "isKeyguardShowing=false", stderr: "" };
			if (joined.includes("input tap")) {
				const [x, y] = args.slice(-2).map(Number);
				taps.push([x, y]);
				screen = tip;
			}
			if (joined.includes("KEYCODE_BACK")) screen = list;
			return { status: 0, stdout: "", stderr: "" };
		};
		const phone = Object.assign(adb, {
			droid: (args: string[]) => ({ status: 0, stdout: args[0] === "dump" ? screen : "", stderr: "" }),
		});
		const batch = {
			id: "b",
			status: "approved" as const,
			signature: "",
			runHour: 19,
			runMinute: 0,
			approvedAt: "2026-11-06T10:00:00.000Z",
			items: [
				item("LG 휘센 FQ161DKEW 스탠드 에어컨", "price-only", 280000),
				item("LG 김치냉장고 K419TS15E", "bump", 290000),
			],
		};
		runApprovedOnPhone(batch, phone, undefined, {
			log: quietLog(),
			findSerial: () => SERIAL,
			book: { previousBumpCount: () => 0, recordBump: () => {}, recordCooldown: () => {} },
		});
		// 목록 위쪽 휘센(가격만)이 먼저 배치돼 있어도 첫 탭은 아래쪽 김치냉장고의 끌어올리기 버튼이다.
		expect(taps[0][1]).toBeGreaterThan(1900);
		const more = taps.findIndex(([x]) => x === 963);
		expect(more).toBeGreaterThan(0);
	}, 40000);
});

describe("목록이 맨 위로 되돌아갈 때", () => {
	const SERIAL = "192.0.2.9:5555";
	const SLOTS = [1010, 1602];
	const tip = `<hierarchy><node text="판매팁: 2일 후에 끌어올릴 수 있어요" content-desc="" bounds="[40,700][1040,760]" /></hierarchy>`;

	function node(text: string, desc: string, x1: number, y1: number, x2: number, y2: number) {
		return `<node text="${text}" content-desc="${desc}" class="android.view.View" bounds="[${x1},${y1}][${x2},${y2}]" />`;
