describe("예약중 글", () => {
	const SERIAL = "192.0.2.9:5555";
	const xml = readFileSync(resolve(import.meta.dir, "fixtures/sales-reserved.xml"), "utf8");
	const title = "쿠자 316 통 5중 스텐 프라이팬 2개";

	function phone(taps: string[][]) {
		return (args: string[]) => {
			const joined = args.join(" ");
			if (args[0] === "mdns") return { status: 0, stdout: "x _adb-tls-connect._tcp 192.0.2.9:5555\n", stderr: "" };
			if (args[0] === "devices") return { status: 0, stdout: "192.0.2.9:5555\tdevice\n", stderr: "" };
			if (joined.includes("getprop")) return { status: 0, stdout: "SM-X000\n", stderr: "" };
			if (joined.includes("dumpsys window")) return { status: 0, stdout: "isKeyguardShowing=false", stderr: "" };
			if (joined.includes("cat /sdcard/window_dump.xml")) return { status: 0, stdout: xml, stderr: "" };
			if (joined.includes("input tap")) taps.push(args);
			return { status: 0, stdout: "", stderr: "" };
		};
	}

	const batch = {
		id: "b",
		status: "approved" as const,
		signature: "",
		runHour: 19,
		runMinute: 0,
		approvedAt: "2026-10-30T10:00:00.000Z",
		items: [
			{
				id: "kuja",
				title,
				action: "price-only" as const,
				proposedPrice: 120000,
				snapshot: { price: 130000, hearts: 28, views: 0, chats: 0 },
			},
		],
	};

	function book(reserved: string[]) {
		return {
			previousBumpCount: () => 0,
			recordBump: () => {},
			recordCooldown: () => {},
			recordReserved: (id: string) => reserved.push(id),
		};
	}

	/** `.droid` 가 붙은 AdbExec. 화면 XML 은 droid dump 가 주고, adb 로는 덤프를 읽지 않는다. */
	function droidPhone(adbCalls: string[][], droidCalls: string[][]) {
		const adb: AdbExec = (args) => {
			adbCalls.push(args);
			if (args.join(" ").includes("dumpsys window"))
				return { status: 0, stdout: "isKeyguardShowing=false", stderr: "" };
			return { status: 0, stdout: "", stderr: "" };
		};
		return Object.assign(adb, {
			droid: (args: string[]) => {
				droidCalls.push(args);
				return { status: 0, stdout: args[0] === "dump" ? xml : "", stderr: "" };
			},
		});
	}

	test("폰 화면이 예약중이면 저장소가 몰라도 누르지 않고 예약중으로 기록한다", () => {
		const taps: string[][] = [];
		const reserved: string[] = [];
		const run = runApprovedOnPhone(batch, phone(taps), undefined, {
			log: quietLog(),
			// 폰 찾기는 droid 가 한다. 여기서는 이미 찾은 시리얼을 넣는다.
			findSerial: () => SERIAL,
			book: book(reserved),
		});
		expect(run).toMatchObject({ pricedOnly: 0, bumped: 0, skipped: 1, stopped: false });
		expect(taps).toEqual([]);
		expect(reserved).toEqual(["kuja"]);
	});

	test("droid 가 있으면 화면은 droid dump 로 읽고 uiautomator 는 부르지 않는다", () => {
		const adbCalls: string[][] = [];
		const droidCalls: string[][] = [];
		const reserved: string[] = [];
		const run = runApprovedOnPhone(batch, droidPhone(adbCalls, droidCalls), undefined, {
			log: quietLog(),
			findSerial: () => SERIAL,
			book: book(reserved),
		});

		expect(run).toMatchObject({ pricedOnly: 0, bumped: 0, skipped: 1, stopped: false });
		expect(reserved).toEqual(["kuja"]);
		expect(droidCalls).toContainEqual(["dump", "--serial", SERIAL]);
		expect(adbCalls.some((args) => args.includes("uiautomator") || args.includes("cat"))).toBe(false);
	});
});

