type Tally = { bumped: number; pricedOnly: number; skipped: number; already: number; stop: boolean };

/**
 * 승인 글을 폰에서 처리한다. 당근 목록은 마지막 노출이 최근인 글이 위, 오래된 글이 아래다. 맨 아래로 내려간 뒤
 * 위로 한 번만 걸으며 만나는 대로 처리한다(끌어올리기와 가격만 수정을 함께). 노출이 가장 오래된 글이 먼저 끝나고,
 * 중간에 실패하거나 멈춰도 급한 글이 먼저 처리돼 있다. 끌어올리기 대상은 노출이 오래된 글이라 대부분 아래쪽에 있어서
 * 맨 위로 되돌아가는 두 번째 걷기가 필요 없다.
 */
function walkApproved(
	serial: string,
	exec: AdbExec,
	ops: ScreenOp[],
	batch: BatchFile,
	listPrices?: ReadonlyMap<string, number>,
	book?: BumpBook,
): Tally {
	const tally: Tally = { bumped: 0, pricedOnly: 0, skipped: 0, already: 0, stop: false };
	const pending = new Map(batch.items.map((item) => [item.title, item]));
	for (const item of batch.items) {
		const listed = listPrices?.get(item.id);
		if (listed === undefined || !alreadyAppliedToday(listed, item.proposedPrice, item.snapshot.price)) continue;
		tally.skipped += 1;
		tally.already += 1;
		noteSkip(item.title, "목록 가격이 승인된 오늘 가격과 같아서");
		pending.delete(item.title);
	}
	if (pending.size === 0) return tally;
	walkUp(serial, exec, ops, pending, tally, book);
	return tally;
}

function walkUp(
	serial: string,
	exec: AdbExec,
	ops: ScreenOp[],
	pending: Map<string, BatchItem>,
	tally: Tally,
	book?: BumpBook,
) {
	scrollToEdge(serial, exec, ops, "bottom");
	let prev = "";
	let stuck = 0;
	let page = 0;
	for (let turn = 0; turn < 60 && page < 24 && pending.size > 0; turn++) {
		if (stopRequested()) {
			tally.stop = true;
			return;
		}
		let reread = false;
		const xml = settledXml(serial, exec);
		const nodes = parseNodes(xml);
		const parsed = parseSalesDump(xml);
		if (parsed.ok) {
			// 아래에서 위로 걸을 때는 화면 아래 카드부터. 오래 노출 안 된 글이 먼저다.
			for (const card of [...parsed.cards].reverse()) {
				const item = pending.get(card.title);
				if (!item) continue;
				// 예약중 글은 거래 약속이 잡혀 있다. 저장소가 아직 모르더라도 폰 화면이 예약중이면 건드리지 않는다.
				if (card.reserved) {
					tally.skipped += 1;
					noteSkip(item.title, "당근에서 예약중이라서");
					book?.recordReserved?.(item.id);
					pending.delete(item.title);
					continue;
				}
				if (alreadyAppliedToday(card.price, item.proposedPrice, item.snapshot.price)) {
					tally.skipped += 1;
					tally.already += 1;
					noteSkip(item.title, "카드 가격이 승인된 오늘 가격과 같아서");
					pending.delete(item.title);
					continue;
				}
				const verdict = guardSnapshot(item.snapshot, card);
				if (!verdict.run) {
					tally.skipped += 1;
					noteSkip(item.title, "가격이 승인 때와 달라서");
					pending.delete(item.title);
					continue;
				}
				const visible = item.action === "bump" ? cardBump(nodes, item.title) : moreFor(nodes, item.title);
				if (!visible) continue;
				const done =
					item.action === "bump"
						? bumpOne(serial, exec, ops, item, false, book)
						: priceOne(serial, exec, ops, item, false);
				pending.delete(item.title);
				if (done === "stop") {
					backToSales(serial, exec, ops);
					tally.stop = true;
					return;
				}
				if (done === "bump") tally.bumped += 1;
				else if (done === "price") tally.pricedOnly += 1;
				else tally.skipped += 1;
				if (stopRequested()) {
					tally.stop = true;
					return;
				}
				// 끌어올린 글은 목록 맨 위로 옮겨 가 화면 배치가 바뀐다. 이 덤프의 나머지 카드는 믿지 않고 다시 읽는다.
				if (done === "bump") {
					reread = true;
					break;
				}
			}
		}
		if (pending.size === 0) break;
		if (reread) continue;
		const key = parsed.ok ? parsed.cards.map((card) => card.title).join("|") : "";
		if (page > 0 && key !== "" && key === prev) {
			stuck += 1;
			if (stuck >= 2) break;
		} else {
			stuck = 0;
		}
		prev = key;
		swipeList(serial, exec, ops, "남은 승인 글을 보러", "back");
		page += 1;
	}
	for (const title of pending.keys()) {
		tally.skipped += 1;
		noteSkip(title, "판매중 목록에서 제목을 못 찾음");
	}
}

