content.text:
		expect(exposureAgeDays({ bumpAgoDays: null, postedAgoDays: 21 })).toBe(21);
		expect(exposureAgeDays({ bumpAgoDays: null, postedAgoDays: null })).toBeNull();
		expect(exposureAgeDays({ bumpAgoDays: null })).toBeNull();
	});

	test("노출이 2일 미만인 글만 최근 노출이다", () => {
		expect(MIN_BUMP_AGE_DAYS).toBe(2);
		expect(recentlyExposed({ bumpAgoDays: 1 })).toBe(true);
		expect(recentlyExposed({ bumpAgoDays: null, postedAgoDays: 1 })).toBe(true);
		expect(recentlyExposed({ bumpAgoDays: 2 })).toBe(false);
		expect(recentlyExposed({ bumpAgoDays: null, postedAgoDays: null })).toBe(false);
	});

	test("노출이 오래된 글은 하트가 적은 글보다 먼저다", () => {
		const quiet = listing({ id: "quiet", title: "가", price: 10_000, hearts: 1, bumpAgoDays: 4 });
		const stale = listing({
			id: "stale",
			title: "나",
			price: 10_000,
			hearts: 7,
			bumpAgoDays: null,
			postedAgoDays: 21,
		});
		const sorted = [quiet, stale].sort((left, right) => compareBumpOrder(left, right, TODAY));
		expect(sorted.map((item) => item.id)).toEqual(["stale", "quiet"]);
	});

	test("끌올한 적 없이 게시만 한 글도 게시 나이로 끼어든다", () => {
		const bumped = listing({ id: "bumped", title: "가", price: 10_000, hearts: 0, bumpAgoDays: 1 });
		const posted = listing({
			id: "posted",
			title: "나",
			price: 10_000,
			hearts: 9,
			bumpAgoDays: null,
			postedAgoDays: 3,
		});
		const sorted = [bumped, posted].sort((left, right) => compareBumpOrder(left, right, TODAY));
		expect(sorted.map((item) => item.id)).toEqual(["posted", "bumped"]);
	});

	test("노출 나이가 같으면 마감 빠른 순 → 하트 적은 순 → 가격 높은 순", () => {
		const rows = [
			listing({ id: "a", title: "가", price: 100_000, hearts: 2, bumpAgoDays: 5, until: "2026-10-29" }),
			listing({ id: "b", title: "나", price: 100_000, hearts: 0, bumpAgoDays: 5, until: "2026-10-29" }),
			listing({ id: "c", title: "다", price: 100_000, hearts: 2, bumpAgoDays: 5, until: "2026-10-27" }),
			listing({ id: "d", title: "라", price: 200_000, hearts: 2, bumpAgoDays: 5, until: "2026-10-29" }),
		];
		const sorted = rows.sort((left, right) => compareBumpOrder(left, right, TODAY)).map((item) => item.id);
		expect(sorted).toEqual(["c", "b", "d", "a"]);
	});

	test("노출 나이가 같으면 하트가 많아도 마감이 가까운 글이 먼저다(휘센이 하트 때문에 밀린 날)", () => {
		const hwisen = listing({ id: "hwisen", title: "LG 휘센", price: 110_000, hearts: 4, bumpAgoDays: 5, until: "2026-10-28" });
		const ulanzi = listing({ id: "ulanzi", title: "울란지", price: 26_000, hearts: 3, bumpAgoDays: 5, until: "2026-11-20" });
		const sorted = [ulanzi, hwisen].sort((left, right) => compareBumpOrder(left, right, TODAY));
		expect(sorted.map((item) => item.id)).toEqual(["hwisen", "ulanzi"]);
		const fillers = Array.from({ length: 5 }, (_, index) =>
			listing({ id: `f${index}`, title: `f${index}`, price: 10_000, hearts: 0, bumpAgoDays: 5, until: "2026-11-20" }),
		);
		const bumped = planOf([...fillers, ulanzi, hwisen])
			.filter((proposal) => proposal.action === "bump")
			.map((proposal) => proposal.id);
		expect(bumped).toHaveLength(6);
		expect(bumped).toContain("hwisen");
		expect(bumped).not.toContain("ulanzi");
	});

	test("노출이 2일 미만이면 fresh 로 건너뛰고 하루 칸도 쓰지 않는다", () => {
		const recent = listing({ id: "r", title: "r", price: 10_000, hearts: 0, bumpAgoDays: 1 });
		const [proposal] = planOf([recent]);
		expect(proposal).toMatchObject({ action: "skip", skipReason: "fresh", blocked: "fresh" });
		expect(summarize([proposal]).held).toBe(0);
	});

	test("끌올한 적 없는 새 글도 게시 나이로 fresh 다", () => {
		const [proposal] = planOf([
			listing({ id: "p", title: "p", price: 10_000, hearts: 0, bumpAgoDays: null, postedAgoDays: 1 }),
		]);
		expect(proposal).toMatchObject({ action: "skip", skipReason: "fresh" });
	});

	test("fresh 글도 내릴 가격이 있으면 가격만 내린다", () => {
		const [proposal] = planOf([
			aimed({ id: "f", title: "f", price: 50_000, hearts: 0, target: 45_000, bumpAgoDays: 1 }),
		]);
		expect(proposal).toMatchObject({ action: "price-only", skipReason: null, blocked: "fresh", price: 45_000 });
	});

	test("노출 시점을 못 읽은 글은 막지 않고 맨 앞에 둔다", () => {
		const unknown = listing({ id: "u", title: "가", price: 10_000, hearts: 9 });
		const day3 = listing({ id: "d", title: "나", price: 10_000, hearts: 0, bumpAgoDays: 3 });
		expect(planOf([unknown])[0].action).toBe("bump");
		const sorted = [day3, unknown].sort((left, right) => compareBumpOrder(left, right, TODAY));
		expect(sorted.map((item) => item.id)).toEqual(["u", "d"]);
	});
});

describe("승인 화면의 제안", () => {
	const rows: { name: string; input: Listing; action: "bump" | "price-only" | "skip"; price: number; note?: string }[] =
		[
			{
				name: "하트 0 · 오늘 타겟 45,000",
				input: aimed({ id: "a", title: "가", price: 50_000, hearts: 0, target: 45_000 }),
				action: "bump",
				price: 45_000,
			},
			{
				name: "하트 2 · 오늘 타겟 5,000",
				input: aimed({ id: "b", title: "나", price: 6_000, hearts: 2, target: 5_000 }),
				action: "bump",
				price: 5_000,
