export type FlowPoint = PricePoint & {
	/** 지금 화면의 가격 한 점. 직선의 날짜별 가격이 아니다 */
	current?: true;
};

/**
 * 가격 흐름의 맨 앞에 지금 가격을 붙인다. 오늘 직선 가격이 지금 가격과 다르면
 * (건너뛴 날이 쌓였거나 타겟을 새로 그은 때) `오늘`만 보여 주면 지금 가격에서 어떻게 가는지 읽히지 않는다.
 */
export function flowFromNow(price: number, path: PricePoint[]): FlowPoint[] {
	if (path.length === 0) return [];
	return path[0].price === price ? path : [{ date: path[0].date, price, current: true }, ...path];
}

/** 마지막 노출 후 지난 날. 끌올 문구가 있으면 그것, 없으면 게시 시점. 둘 다 못 읽었으면 null. */
export function exposureAgeDays(listing: Pick<Listing, "bumpAgoDays" | "postedAgoDays">): number | null {
	return listing.bumpAgoDays ?? listing.postedAgoDays ?? null;
}

/** 마지막 노출이 2일 미만인가. 노출 시점을 못 읽었으면 막지 않는다. */
export function recentlyExposed(listing: Pick<Listing, "bumpAgoDays" | "postedAgoDays">): boolean {
	const age = exposureAgeDays(listing);
	return age !== null && age < MIN_BUMP_AGE_DAYS;
}

/** 마감까지 남은 날. 날짜 없거나 잘못되면 맨 뒤. 지난 마감은 오늘(1)과 같다. */
export function untilUrgency(until: string | null, today: string): number {
	if (until === null) return Number.POSITIVE_INFINITY;
	const span = remainingDays(today, until);
	if (span === null) return Number.POSITIVE_INFINITY;
	return span < 1 ? 1 : span;
}

/**
 * 끌올 칸 순서: 마지막 노출이 오래된 순(노출 시점을 못 읽은 글이 맨 앞) → 하트 적은 순 →
 * 마감 빠른 순 → 가격 높은 순 → 제목 오름차순.
 */
export function compareBumpOrder(a: Listing, b: Listing, today: string): number {
	const left = exposureAgeDays(a) ?? Number.POSITIVE_INFINITY;
	const right = exposureAgeDays(b) ?? Number.POSITIVE_INFINITY;
	if (left !== right) return left > right ? -1 : 1;
	if (a.hearts !== b.hearts) return a.hearts - b.hearts;
	const urgentA = untilUrgency(a.until, today);
	const urgentB = untilUrgency(b.until, today);
	if (urgentA !== urgentB) return urgentA - urgentB;
	if (a.price !== b.price) return b.price - a.price;
	return a.title.localeCompare(b.title, "ko");
}

/** 글당 15회를 채웠는가. */
export function atMaxBumps(listing: Pick<Listing, "bumpCount">): boolean {
	return (listing.bumpCount ?? 0) >= MAX_BUMPS;
}

/** 시각 인자. ms 숫자와 Date를 모두 받는다. */
export type Clock = number | Date;

function ms(clock: Clock): number {
	return clock instanceof Date ? clock.getTime() : clock;
}

/** 폰이 알려 준 다음 끌올 시각이 아직 지나지 않았는가. ISO가 아니면 모르는 것으로 본다. */
export function inCooldown(listing: Pick<Listing, "nextBumpAt">, now: Clock = Date.now()): boolean {
	if (listing.nextBumpAt === null) return false;
	const at = Date.parse(listing.nextBumpAt);
	return !Number.isNaN(at) && at > ms(now);
}

/** 15회 미만이고 쿨타임이 지났을 때만 끌어올릴 수 있다. */
export function bumpEligible(listing: Pick<Listing, "bumpCount" | "nextBumpAt">, now: Clock = Date.now()): boolean {
	return !atMaxBumps(listing) && !inCooldown(listing, now);
}

/** 오늘 끌어올리지 못하는 까닭. 한도 말고는 없으면 null. */
function blockedBy(listing: Listing, now: Clock): Exclude<Blocked, "daily-limit"> | null {
	if (atMaxBumps(listing)) return "max-bumps";
	if (inCooldown(listing, now)) return "cooldown";
	if (recentlyExposed(listing)) return "fresh";
	return null;
}

function bumpingIds(listings: Listing[], rules: RuleSet, today: string, now: Clock): Set<string> {
	const candidates = listings
		.filter((listing) => listing.included && !listing.reserved && blockedBy(listing, now) === null)
		.sort((left, right) => compareBumpOrder(left, right, today));
	const limit = Math.max(0, rules.dailyLimit - bumpedToday(listings, today, now));
	return new Set(candidates.slice(0, limit).map((listing) => listing.id));
}

/** 서울 날짜로 오늘 이미 끌어올린 글 수. 하루 한도는 회차가 아니라 날마다 센다. */
export function bumpedToday(listings: Pick<Listing, "bumpedAt">[], today: string, now: Clock = Date.now()): number {
	return listings.filter((listing) => {
		if (listing.bumpedAt === null) return false;
		const at = Date.parse(listing.bumpedAt);
		return !Number.isNaN(at) && at <= ms(now) && seoulToday(at) === today;
	}).length;
}

/**
 * 노출이 오래됐고 곧 끌어올릴 수 있는 글(하루 한도·쿨타임에 걸린 글)은 인하를 미룬다.
 * 15회를 채운 글은 끌어올릴 날이 없어 미루면 영영 못 내리므로 제외한다. 마감 마지막 날도 타겟에 맞춰야 해서 미루지 않는다.
 */
function holdsCutForBump(listing: Listing, blocked: Blocked, remainingDays: number): boolean {
	if (blocked !== "daily-limit" && blocked !== "cooldown") return false;
	const age = exposureAgeDays(listing);
	return age !== null && age >= STALE_EXPOSURE_DAYS && remainingDays > 1;
}

/** 지금 화면과 규칙이 고르는 글 하나의 제안. 입력 순서를 유지한다. */
export function proposeBatch(
	listings: Listing[],
	rules: RuleSet,
	today = seoulToday(),
