function bumpOne(
	serial: string,
	exec: AdbExec,
	ops: ScreenOp[],
	item: BatchItem,
	dry: boolean,
	book?: BumpBook,
): "bump" | "skip" | "stop" {
	const title = item.title;
	const price = item.proposedPrice;
	if (stopRequested()) return "stop";
	let sheet: string | null = null;
	// 탭이 움직이는 목록에 떨어져 창이 안 열릴 수 있다. 멈춘 화면을 다시 읽어 한 번 더 누른다.
	for (let attempt = 0; attempt < 2 && !sheet; attempt++) {
		const xml = attempt === 0 ? dumpXml(serial, exec) : settledXml(serial, exec);
		const node = cardBump(parseNodes(xml), title);
		if (!node) return "skip";
		const point = center(node);
		tap(
			serial,
			exec,
			ops,
			point.x,
			point.y,
			"카드 끌어올리기",
			`「${title}」을 ${price.toLocaleString("ko-KR")}원으로 끌어올리려고`,
		);
		if (stopRequested()) return "stop";
		sheet = waitFor(serial, exec, (text) => onBumpSheet(text) || cooldownTip(text), attempt === 0 ? 3000 : 8000);
	}
	if (!sheet || cooldownTip(sheet)) {
		nowCooldown(item.id, sheet, book);
		backToSales(serial, exec, ops);
		return "skip";
	}
	// 목록이 다시 그려지는 사이 다른 카드를 눌렀을 수 있다. 연 창의 제목이 다르면 아무것도 바꾸지 않고 닫는다.
	if (!showsTitle(sheet, title)) {
		noteSkip(title, "연 끌어올리기 창의 제목이 달라서");
		backToSales(serial, exec, ops);
		return "skip";
	}
	const ready = ensurePrice(serial, exec, ops, sheet, price, dry);
	if (ready === "stop") return "stop";
	if (dry) {
		backToSales(serial, exec, ops);
		return ready === "skip" ? "skip" : "bump";
	}
	if (ready === "skip") {
		backToSales(serial, exec, ops);
		return "skip";
	}
	// 가격을 하나도 확정하지 않은 채로 멈춘다. 그만두기를 먼저 누른다.
	if (stopRequested()) {
		backToSales(serial, exec, ops);
		return "stop";
	}
	if (
		!confirmMatchingPrice(
			serial,
			exec,
			ops,
			price,
			CONFIRM_BUMP,
			`「${title}」 ${price.toLocaleString("ko-KR")}원 확정`,
		)
	) {
		backToSales(serial, exec, ops);
		return "stop";
	}
	recordBumped(item.id, book);
	backToSales(serial, exec, ops);
	return "bump";
}

