			return opened ? "판매관리가 열림" : `판매관리가 안 열림 (지금 화면: ${focusOf(serial, exec)})`;
		},
		() => opened,
	);
}

function onSales(xml: string): boolean {
	return xml.includes("판매관리") && (xml.includes("끌어올리기") || xml.includes("판매중 "));
}

function backToSales(serial: string, exec: AdbExec, ops: ScreenOp[]) {
	for (let i = 0; i < 4; i++) {
		const xml = dumpXml(serial, exec);
		if (xml.includes("판매관리") && !xml.includes("그만두기")) return;
		const discard = parseNodes(xml).find((node) => node.text === "그만두기");
		if (discard) {
			const at = center(discard);
			act(
				serial,
				{ cmd: "tap", action: "그만두기를 누름", reason: "바꾼 가격이 저장되면 안 되어서" },
				() => {
					exec(["-s", serial, "shell", "input", "tap", String(at.x), String(at.y)]);
					sleep(400);
				},
				() => "수정을 저장하지 않고 닫음",
			);
			continue;
		}
		act(
			serial,
			{ cmd: "back", action: "뒤로 감", reason: "판매중 목록으로 돌아가려고" },
			() => {
				ops.push({ kind: "back" });
				exec(["-s", serial, "shell", "input", "keyevent", "KEYCODE_BACK"]);
				sleep(400);
			},
			() => (dumpXml(serial, exec).includes("판매관리") ? "판매관리로 돌아옴" : "아직 다른 화면"),
		);
	}
}

function waitFor(serial: string, exec: AdbExec, pred: (xml: string) => boolean, ms: number): string | null {
	const log = journal;
	const startMs = log?.now() ?? 0;
	const start = Date.now();
	let found: string | null = null;
	while (Date.now() - start < ms) {
		if (stopRequested()) break;
		const xml = dumpXml(serial, exec, true);
		if (pred(xml)) {
			found = xml;
			break;
		}
		sleep(350);
	}
	const endMs = log?.now() ?? 0;
	log?.next(
		{
			cmd: "wait",
			action: "화면을 기다림",
			reason: `${ms}ms 안에 기대한 화면이 되기를 기다려서`,
			result: found ? "기대한 화면이 됨" : stopRequested() ? "중단 요청으로 멈춤" : "기다려도 안 바뀜",
			ok: found !== null,
		},
		{ startMs, endMs },
	);
	return found;
}

function dumpXml(serial: string, exec: AdbExec, fresh = false): string {
	if (!fresh && screen && screen.serial === serial && Date.now() - screen.at < SCREEN_REUSE_MS) return screen.xml;
	const log = serial === journalSerial ? journal : null;
	const startMs = log?.now() ?? 0;
	const xml = dumpScreen(serial, exec);
	const endMs = log?.now() ?? 0;
	log?.next(
		{
			cmd: "dump",
			action: "화면 덤프",
			reason: "지금 화면을 읽으려고",
			target: "",
			result: `${xml.length}바이트`,
			ok: xml.length > 0,
		},
		{ startMs, endMs },
	);
	screen = xml.length > 0 ? { serial, xml, at: Date.now() } : null;
	return xml;
}

/**
 * 목록이 멈춘 화면을 읽는다. 스와이프 뒤 목록은 플링으로 더 미끄러지므로, 덤프 좌표로 누르면 빈 곳이나 움직이는 목록을 눌러
 * 메뉴가 안 열린다(2026-11-06 19:00 회차에서 로맨틱무브 이하 6건이 이렇게 건너뛰어졌다). `settledDump`로 연속 두 덤프가 같을 때까지 기다린다.
 */
function settledXml(serial: string, exec: AdbExec): string {
	return settledDump(() => dumpXml(serial, exec, true), sleep);
}

function wake(serial: string, exec: AdbExec) {
	exec(["-s", serial, "shell", "input", "keyevent", "KEYCODE_WAKEUP"]);
}

function readLocked(serial: string, exec: AdbExec): boolean {
	const blob = exec(["-s", serial, "shell", "dumpsys", "window"]).stdout;
	return keyguardLocked(blob) !== false;
}

function tap(serial: string, exec: AdbExec, ops: ScreenOp[], x: number, y: number, label: string, reason = label) {
	if (forbiddenLabel(label, label)) {
		noteSkip(label, "누르지 않는 버튼이라서");
		return;
	}
	act(
		serial,
